def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    m, n = N, N  # Get the dimensions of the grid
    # Create the DP arrays for both paths
    dp1 = [[0] * (n + 2) for _ in range(m + 2)]
    dp2 = [[0] * (n + 2) for _ in range(m + 2)]

    # Populate the DP array for the first path
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            val, x_move, y_move = grid_values[i - 1][j - 1]
            dp1[i][j] = val + max(dp1[i - 1][j - 1],
                                   dp1[i - 1][j + 1],
                                   dp1[i][j - 1])

    # Populate the DP array for the second path
    for i in range(m, 0, -1):
        for j in range(n, 0, -1):
            val, x_move, y_move = grid_values[i - 1][j - 1]
            dp2[i][j] = val + max(dp2[i + 1][j - 1],
                                   dp2[i + 1][j + 1],
                                   dp2[i][j + 1])

    # Find the intersection point of the two paths
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            dp1[i][j] += dp2[i + j][j - i] if i <= j else 0
            dp2[i][j] += dp1[i - j][j + i] if i >= j else 0

    # Return the maximum value between the two paths
    return max(max(dp1[i][j] for j in range(1, n + 1)), max(dp2[i][j] for j in range(1, n + 1)))

