                    if pairs[i][1] < min_pre:
                        min_pre = pairs[i][1]
                    if pairs[i][1] > max_pre:
                        max_pre = pairs[i][1]
                    i += 1
            total_pairs = 0
            if min_pre > 0:
                total_pairs += (pre - 1) * (K - 1) * (L - 1)
            if min_pre == 0:
                total_pairs += (K - 1) * (L - 1)
            if max_pre < N:
                total_pairs += (N - max_pre - 1) * (K - 1) * (L - 1)
            if max_pre == N:
                total_pairs += (K - 1) * (L - 1)
            if pre != pos:
                total_pairs += ((min_pre - pre) * (K - 1) + (pos - max_pre) * (K - 1)) * (L - 1)
            pre = pos
        return total_pairs

    # Generate all possible positions for K + L aisles
    for i in range(K + L):
        for positions in combinations(range(M+K+L-i), K+L-i):
            aisle_positions.add(tuple(positions))

