def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if not isinstance(n, int) or n <= 0:
        raise ValueError("The budget must be a positive integer.")
    if not isinstance(m, int) or m <= 0:
        raise ValueError("The number of items must be a positive integer.")
    if not all(isinstance(item, tuple) and len(item) == 2 for item in items):
        raise ValueError("The items list must contain tuples with two integers each.")
    if any(price <= 0 or importance <= 0 for price, importance in items):
        raise ValueError("The price and importance values must be positive integers.")
    if m > len(items):
        raise ValueError("The number of items exceeds the given count.")

    # Initialize a 2D dp array where dp[i][j] will store the maximum importance value
    # that can be achieved with budget i when considering the first j items
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            price, importance = items[j - 1]
            # If the current item is within the budget
            if i >= price:
                # Take the maximum between not considering the current item
                # and considering the current item
                dp[i][j] = max(dp[i][j - 1], dp[i - price][j - 1] + importance)
            else:
                # Since the current item is not within the budget, skip it
                dp[i][j] = dp[i][j - 1]

    # The maximum importance value can be achieved with the total budget and all items
    return dp[n][m]

