def catalan_number(n: int) -> int:
    # Base case: C(0) is 1
    if n == 0:
        return 1

    # Initialize the list to store Catalan numbers
    catalan = [0 for _ in range(n + 1)]
    catalan[0] = Catalan[1] = 1

    # Fill in the Catalan numbers using the recursive formula
    for i in range(2, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]

    return catalan[n]

