def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    def factorial(n):
        result = 1
        for i in range(1, n + 1):
            result = (result * i) % MOD
        return result

    def combination(n, k):
        return factorial(n) // (factorial(k) * factorial(n - k))

    if n == 0:
        return 0

    # Initialize the number of arrangements based on the number of available flowers
    if m == n:
        return 1

    dp = [0] * m
    dp[0] = 1

    # Calculate the number of arrangements based on the previous number of arrangements
    for i in range(1, m):
        for j in range(min(i, n) + 1):
