def next_permutation(perm: list) -> bool:
    n = len(perm)
    # Traverse from the end to the beginning of the list
    for i in range(n - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            # Find the smallest element that is greater than perm[i] from the right
            for j in range(n - 1, i, -1):
                if perm[j] > perm[i]:
                    # Swap perm[i] and perm[j]
                    perm[i], perm[j] = perm[j], perm[i]
                    # Reverse the sequence from i + 1 to the end
                    perm[i + 1:] = reversed(perm[i + 1:])
                    return True
    # If no next permutation exists, return False
    perm.sort()
    return False

